<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use App\Support\Audits;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;

class ProcurementController extends Controller
{
    public function workspace(Request $r) { $size=min(max((int)$r->input('pageSize',250),1),500); $page=DB::table('rfqs')->whereNull('deleted_at')->latest('id')->paginate($size); $ids=collect($page->items())->pluck('id'); if($ids->isEmpty())return response()->json(['data'=>['rfqs'=>[],'items'=>[],'bids'=>[],'evaluations'=>[]],'meta'=>['page'=>$page->currentPage(),'pageSize'=>$page->perPage(),'total'=>$page->total()]]); $items=DB::table('rfq_items')->whereIn('rfq_id',$ids)->orderBy('rfq_id')->orderBy('line_no')->get(); $bids=DB::table('bids')->whereIn('rfq_id',$ids)->orderBy('total_price')->get(); $bidIds=$bids->pluck('id'); $evaluations=$bidIds->isEmpty()?collect():DB::table('bid_evaluations')->join('committee_members','bid_evaluations.committee_member_id','=','committee_members.id')->whereIn('bid_evaluations.bid_id',$bidIds)->select('bid_evaluations.*','committee_members.member_name','committee_members.position_title')->get(); return response()->json(['data'=>['rfqs'=>$page->items(),'items'=>$items,'bids'=>$bids,'evaluations'=>$evaluations],'meta'=>['page'=>$page->currentPage(),'pageSize'=>$page->perPage(),'total'=>$page->total()]]); }
    public function orderAction(Request $r, int $id, string $action) { return $this->transition($r,'procurement_orders',$id,$action,['submit'=>'pending','approve'=>'approved','reject'=>'draft','start'=>'in_progress','complete'=>'completed','cancel'=>'cancelled']); }
    public function rfqAction(Request $r, int $id, string $action) { return $this->transition($r,'rfqs',$id,$action,['publish'=>'open','close'=>'closed','evaluate'=>'evaluation','cancel'=>'cancelled']); }
    public function contractAction(Request $r, int $id, string $action) { return $this->transition($r,'contracts',$id,$action,['activate'=>'active','complete'=>'completed','cancel'=>'cancelled']); }
    private function transition(Request $r,string $table,int $id,string $action,array $states) { abort_unless(isset($states[$action]),404); $row=DB::table($table)->where('id',$id)->first(); abort_unless($row,404); if($table==='rfqs' && $action==='publish' && DB::table('rfq_items')->where('rfq_id',$id)->count()===0) return response()->json(['error'=>['code'=>'VALIDATION_ERROR','message'=>'An RFQ must have at least one item.']],422); if($table==='contracts' && $action==='complete' && $row->progress_percent<100) return response()->json(['error'=>['code'=>'VALIDATION_ERROR','message'=>'Contract progress must be 100% before completion.']],422); DB::table($table)->where('id',$id)->update(['status'=>$states[$action],'updated_at'=>now()]); Audits::write($r,$action,$table,$id,['status'=>$states[$action],'comment'=>$r->input('comment')]); return response()->json(['data'=>DB::table($table)->where('id',$id)->first()]); }

    public function orderItems(Request $r,int $id) { return $this->childList($r,'order_items','procurement_order_id',$id); }
    public function rfqItems(Request $r,int $id) { return $this->childList($r,'rfq_items','rfq_id',$id); }
    public function createOrderItem(Request $r,int $id) { $data=$r->validate(['description'=>'required|string','unit'=>'required|string|max:50','quantity'=>'required|numeric|gt:0','estimated_unit_price'=>'nullable|numeric|min:0']); $data['procurement_order_id']=$id; $data['line_no']=DB::table('order_items')->where('procurement_order_id',$id)->max('line_no')+1; return $this->insertChild($r,'order_items',$data); }
    public function createRfqItem(Request $r,int $id) { $data=$r->validate(['description'=>'required|string','unit'=>'required|string|max:50','quantity'=>'required|numeric|gt:0','estimated_unit_price'=>'nullable|numeric|min:0','technical_specification'=>'nullable|string']); $data['rfq_id']=$id; $data['line_no']=DB::table('rfq_items')->where('rfq_id',$id)->max('line_no')+1; return $this->insertChild($r,'rfq_items',$data); }
    public function inviteVendor(Request $r,int $id) { $data=$r->validate(['vendor_id'=>'required|exists:vendors,id']); $company=DB::table('vendors')->join('companies','vendors.company_id','=','companies.id')->where('vendors.id',$data['vendor_id'])->select('companies.eligibility_status')->first(); if(!$company || $company->eligibility_status!=='active') return response()->json(['error'=>['code'=>'INELIGIBLE_VENDOR','message'=>'Vendor company is not eligible.']],422); DB::table('rfq_vendor_invitations')->updateOrInsert(['rfq_id'=>$id,'vendor_id'=>$data['vendor_id']],['invited_at'=>now(),'created_at'=>now(),'updated_at'=>now()]); Audits::write($r,'invite_vendor','rfqs',$id,$data); return response()->json(['data'=>['rfqId'=>$id]+$data],201); }
    public function bids(Request $r,int $id) { return response()->json(['data'=>DB::table('bids')->where('rfq_id',$id)->orderBy('total_price')->get()]); }
    public function bidEvaluations(Request $r,int $id) { $bid=DB::table('bids')->where('id',$id)->first(); abort_unless($bid,404); return response()->json(['data'=>DB::table('bid_evaluations')->join('committee_members','bid_evaluations.committee_member_id','=','committee_members.id')->where('bid_evaluations.bid_id',$id)->select('bid_evaluations.*','committee_members.member_name','committee_members.position_title')->orderByDesc('bid_evaluations.id')->get()]); }
    public function createBid(Request $r,int $id) { $rfq=DB::table('rfqs')->where('id',$id)->first(); abort_unless($rfq,404); if($rfq->status!=='open'||now()->greaterThan($rfq->closing_at)) return response()->json(['error'=>['code'=>'RFQ_CLOSED','message'=>'The RFQ is not open for bids.']],422); $data=$r->validate(['vendor_id'=>'required|exists:vendors,id','bid_no'=>'nullable|string|max:100','currency'=>'required|in:AFN,USD,EUR','valid_until'=>'required|date','items'=>'required|array|min:1','items.*.rfq_item_id'=>'required|exists:rfq_items,id','items.*.unit_price'=>'required|numeric|min:0','items.*.quantity_offered'=>'required|numeric|gt:0']); $eligible=DB::table('vendors')->join('companies','vendors.company_id','=','companies.id')->where('vendors.id',$data['vendor_id'])->where('companies.eligibility_status','active')->exists(); if(!$eligible)return response()->json(['error'=>['code'=>'INELIGIBLE_VENDOR','message'=>'Vendor is not eligible.']],422); return DB::transaction(function() use($r,$id,$data) { $total=collect($data['items'])->sum(fn($x)=>$x['unit_price']*$x['quantity_offered']); $bid=DB::table('bids')->insertGetId(['rfq_id'=>$id,'vendor_id'=>$data['vendor_id'],'bid_no'=>$data['bid_no']??null,'submitted_at'=>now(),'total_price'=>$total,'currency'=>$data['currency'],'valid_until'=>$data['valid_until'],'status'=>'submitted','created_at'=>now(),'updated_at'=>now()]); foreach($data['items'] as $item) { if(!DB::table('rfq_items')->where('id',$item['rfq_item_id'])->where('rfq_id',$id)->exists()) abort(422,'Invalid RFQ item.'); DB::table('bid_items')->insert(['bid_id'=>$bid,'rfq_item_id'=>$item['rfq_item_id'],'unit_price'=>$item['unit_price'],'quantity_offered'=>$item['quantity_offered'],'line_total'=>$item['unit_price']*$item['quantity_offered'],'created_at'=>now(),'updated_at'=>now()]); } Audits::write($r,'receive_bid','bids',$bid,['total_price'=>$total]); return response()->json(['data'=>DB::table('bids')->where('id',$bid)->first()],201); }); }
    public function createCommittee(Request $r,int $id) { $data=$r->validate(['name'=>'required|string|max:255','members'=>'required|array|min:1','members.*.member_name'=>'required|string|max:255','members.*.user_id'=>'nullable|exists:users,id','members.*.position_title'=>'nullable|string|max:255','members.*.role'=>'required|in:chair,member,secretary']); return DB::transaction(function()use($r,$id,$data){$committee=DB::table('evaluation_committees')->updateOrInsert(['rfq_id'=>$id],['name'=>$data['name'],'status'=>'active','updated_at'=>now(),'created_at'=>now()]);$c=DB::table('evaluation_committees')->where('rfq_id',$id)->first();DB::table('committee_members')->where('evaluation_committee_id',$c->id)->delete();foreach($data['members']as$m)DB::table('committee_members')->insert([...$m,'evaluation_committee_id'=>$c->id,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);Audits::write($r,'create_committee','rfqs',$id,['name'=>$data['name']]);return response()->json(['data'=>$c],201);}); }
    public function committee(Request $r,int $id) { $committee=DB::table('evaluation_committees')->where('rfq_id',$id)->first(); if(!$committee)return response()->json(['data'=>null]); return response()->json(['data'=>['committee'=>$committee,'members'=>DB::table('committee_members')->where('evaluation_committee_id',$committee->id)->where('active',true)->get()]]); }
    public function evaluateBid(Request $r,int $id) { $data=$r->validate(['committee_member_id'=>'required|exists:committee_members,id','score'=>'nullable|numeric|between:0,100','recommendation'=>'required|in:qualified,reject,award,recheck','comments'=>'nullable|string','signature'=>'required|string|max:255']); $bid=DB::table('bids')->where('id',$id)->first();abort_unless($bid,404);$member=DB::table('committee_members')->join('evaluation_committees','committee_members.evaluation_committee_id','=','evaluation_committees.id')->where('committee_members.id',$data['committee_member_id'])->where('evaluation_committees.rfq_id',$bid->rfq_id)->first();if(!$member)return response()->json(['error'=>['code'=>'INVALID_COMMITTEE_MEMBER','message'=>'Member is not assigned to this RFQ.']],422);DB::table('bid_evaluations')->updateOrInsert(['bid_id'=>$id,'committee_member_id'=>$data['committee_member_id']],['score'=>$data['score']??null,'recommendation'=>$data['recommendation'],'comments'=>$data['comments']??null,'signature'=>$data['signature'],'signed_at'=>now(),'status'=>'submitted','updated_at'=>now(),'created_at'=>now()]);Audits::write($r,'evaluate','bids',$id,$data);return response()->json(['data'=>DB::table('bid_evaluations')->where('bid_id',$id)->where('committee_member_id',$data['committee_member_id'])->first()]); }
    public function deleteEvaluation(Request $r,int $bidId,int $evaluationId) { $evaluation=DB::table('bid_evaluations')->where('id',$evaluationId)->where('bid_id',$bidId)->first(); abort_unless($evaluation,404); DB::table('bid_evaluations')->where('id',$evaluationId)->delete(); Audits::write($r,'delete_evaluation','bid_evaluations',$evaluationId); return response()->noContent(); }
    public function recommendAward(Request $r,int $id) { $data=$r->validate(['winning_bid_id'=>'required|exists:bids,id','award_no'=>'required|string|max:100','decision_reason'=>'required|string']);$bid=DB::table('bids')->where('id',$data['winning_bid_id'])->where('rfq_id',$id)->first();if(!$bid)return response()->json(['error'=>['code'=>'INVALID_BID','message'=>'Bid does not belong to this RFQ.']],422);if(DB::table('bid_evaluations')->where('bid_id',$bid->id)->where('recommendation','award')->count()===0)return response()->json(['error'=>['code'=>'EVALUATION_REQUIRED','message'=>'An award recommendation requires an award evaluation.']],422);$award=DB::table('awards')->insertGetId(['rfq_id'=>$id,'winning_bid_id'=>$bid->id,'award_no'=>$data['award_no'],'award_amount'=>$bid->total_price,'currency'=>$bid->currency,'decision_reason'=>$data['decision_reason'],'status'=>'recommended','created_at'=>now(),'updated_at'=>now()]);DB::table('rfqs')->where('id',$id)->update(['status'=>'awarded','updated_at'=>now()]);Audits::write($r,'recommend_award','awards',$award,$data);return response()->json(['data'=>DB::table('awards')->where('id',$award)->first()],201); }
    public function approveAward(Request $r,int $id) { $award=DB::table('awards')->where('id',$id)->first();abort_unless($award,404);DB::table('awards')->where('id',$id)->update(['status'=>'approved','approved_by'=>$r->user()->id,'approved_at'=>now(),'updated_at'=>now()]);Audits::write($r,'approve_award','awards',$id);return response()->json(['data'=>DB::table('awards')->where('id',$id)->first()]); }
    public function progress(Request $r,int $id) { $d=$r->validate(['progress_percent'=>'required|numeric|between:0,100','update_date'=>'required|date','notes'=>'nullable|string']);DB::transaction(function()use($r,$id,$d){DB::table('contracts')->where('id',$id)->update(['progress_percent'=>$d['progress_percent'],'updated_at'=>now()]);DB::table('contract_progress_updates')->insert([...$d,'contract_id'=>$id,'submitted_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);});Audits::write($r,'update_progress','contracts',$id,$d);return response()->json(['data'=>DB::table('contracts')->where('id',$id)->first()]); }
    private function childList(Request $r,string $table,string $key,int $id){return response()->json(['data'=>DB::table($table)->where($key,$id)->orderBy('line_no')->get()]);}
    private function insertChild(Request $r,string $table,array $data){$id=DB::table($table)->insertGetId([...$data,'created_at'=>now(),'updated_at'=>now()]);Audits::write($r,'create',$table,$id,$data);return response()->json(['data'=>DB::table($table)->where('id',$id)->first()],201);}
}
